begin;
set local search_path=public,extensions;
select plan(41);

select has_table('public','reward_source_events','authoritative reward source events exist');
select has_table('public','reward_award_approvals','reward approvals are independent records');
select has_table('public','measurement_baseline_submissions','baseline drafts are separate from verified baselines');
select has_table('public','measurement_baseline_verification_decisions','baseline verification decisions exist');
select has_function('public','record_reward_source_event',array['uuid','text','text','text','text','jsonb','jsonb','text','timestamp with time zone','text','uuid'],'reward source event command exists');
select has_function('public','decide_reward_award',array['uuid','uuid','text','text','text','uuid'],'reward dual-control decision command exists');
select has_function('public','decide_measurement_baseline',array['uuid','text','text','text','uuid'],'baseline review command exists');
select ok((select pg_get_functiondef(p.oid)like'%auth.jwt()%''aal''%'and pg_get_functiondef(p.oid)like'%aal2%'and pg_get_functiondef(p.oid)like'%FINANCE_MANAGER%'and pg_get_functiondef(p.oid)not like'%READ_ONLY_AUDITOR%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='rewards_sensitive_aal2'),'sensitive decisions require an allowed central AAL2 role');
select ok(not has_function_privilege('anon','private.rewards_sensitive_aal2(uuid)','EXECUTE')and not has_function_privilege('authenticated','private.rewards_sensitive_aal2(uuid)','EXECUTE')and not has_function_privilege('service_role','private.rewards_sensitive_aal2(uuid)','EXECUTE'),'sensitive helper is not an API surface');
select ok((select count(*)=4 from pg_trigger t join pg_class c on c.oid=t.tgrelid where c.oid=any(array['public.reward_source_events'::regclass,'public.reward_award_approvals'::regclass,'public.measurement_baseline_submissions'::regclass,'public.measurement_baseline_verification_decisions'::regclass])and t.tgname like'%immutable'and not t.tgisinternal),'new source approval and baseline workflow records are immutable');
select ok((select count(*)=4 and bool_and(c.relrowsecurity)from pg_class c where c.oid=any(array['public.reward_source_events'::regclass,'public.reward_award_approvals'::regclass,'public.measurement_baseline_submissions'::regclass,'public.measurement_baseline_verification_decisions'::regclass])),'all hardening tables enforce RLS');
select ok(not has_table_privilege('authenticated','public.reward_source_events','INSERT')and not has_table_privilege('authenticated','public.reward_award_approvals','UPDATE')and not has_table_privilege('authenticated','public.measurement_baseline_submissions','DELETE'),'direct workflow mutations remain denied');
select ok((select pg_get_functiondef(p.oid)like'%e.event_type<>v.trigger_event%'and pg_get_functiondef(p.oid)like'%e.audience_type<>v.audience_type%'and pg_get_functiondef(p.oid)like'%e.source_reference_type<>p_trigger_reference_type%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='award_reward'),'award binds exact trigger audience and authoritative source reference');
select ok((select pg_get_functiondef(p.oid)like'%reward_award_approvals%'and pg_get_functiondef(p.oid)like'%decision=''APPROVED''%'and pg_get_functiondef(p.oid)like'%APPROVED_REWARD_SOURCE_REQUIRED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='award_reward'),'award requires a persisted approved decision');
select ok((select pg_get_functiondef(p.oid)not like'%RULE_AUTO_APPROVED%'and pg_get_functiondef(p.oid)like'%ap.id::text%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='award_reward'),'award has no automatic or free-text approval fallback');
select ok((select pg_get_functiondef(p.oid)like'%public.issue_credits%'and pg_get_functiondef(p.oid)not like'%insert into public.credit_ledger_entries%'and pg_get_functiondef(p.oid)not like'%update public.credit_wallets%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='award_reward'),'approved rewards still use only the immutable credit RPC');
select ok((select pg_get_functiondef(p.oid)like'%p_to_stage=''PROFILE_STARTED''%'and pg_get_functiondef(p.oid)like'%REFERRAL_PROFILE_TARGET_REQUIRED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='advance_referral_conversion'),'target tenant can only advance its profile-started stage');
select ok((select pg_get_functiondef(p.oid)like'%REFERRAL_VERIFICATION_AAL2_REQUIRED%'and pg_get_functiondef(p.oid)like'%rewards_sensitive_aal2%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='advance_referral_conversion'),'verified and active referral stages require central AAL2 authority');
select ok((select pg_get_functiondef(p.oid)like'%client_compliance_cases%'and pg_get_functiondef(p.oid)like'%provider_profiles%'and pg_get_functiondef(p.oid)like'%AUTHORITATIVE_ORGANIZATION_VERIFICATION_REQUIRED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='advance_referral_conversion'),'referral verification consumes authoritative client or provider status');
select ok((select pg_get_functiondef(p.oid)like'%verified_actor=a%'and pg_get_functiondef(p.oid)like'%REFERRAL_ACTIVATION_DUAL_CONTROL_REQUIRED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='advance_referral_conversion'),'activation must be decided by a second central actor');
select ok((select pg_get_functiondef(p.oid)like'%measurement_baseline_submissions%'and pg_get_functiondef(p.oid)not like'%insert into public.measurement_baselines%'and pg_get_functiondef(p.oid)like'%DRAFT%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='capture_verified_baseline'),'legacy capture entry point now creates only a draft submission');
select ok((select pg_get_functiondef(p.oid)like'%diagnostic_recommendations%'and pg_get_functiondef(p.oid)like'%diagnostic_opportunities%'and pg_get_functiondef(p.oid)like'%client_projects%'and pg_get_functiondef(p.oid)like'%contracts%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='assert_baseline_subject_scope'),'baseline subject IDs are bound to authoritative tenant resources');
select ok((select pg_get_functiondef(p.oid)like'%BASELINE_REVIEW_AAL2_REQUIRED%'and pg_get_functiondef(p.oid)like'%measurement_baseline_verification_decisions%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_measurement_baseline'),'baseline approval is an AAL2 persisted decision');
select ok((select pg_get_functiondef(p.oid)like'%a=s.submitted_by%'and pg_get_functiondef(p.oid)like'%BASELINE_DUAL_CONTROL_REQUIRED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_measurement_baseline'),'baseline submitter cannot approve their own evidence');
select ok((select count(*)=2 from pg_trigger where tgname=any(array['recommendation_roi_approved_baseline_guard','savings_approved_baseline_guard'])and not tgisinternal),'ROI and savings both enforce an independently approved baseline');
select ok((select pg_get_functiondef(p.oid)like'%INDEPENDENTLY_APPROVED_BASELINE_REQUIRED%'and pg_get_functiondef(p.oid)like'%decision=''APPROVED''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='guard_approved_baseline_measurement'),'unapproved legacy baselines cannot create ROI or savings');
select ok((select count(*)=3 and bool_and(pg_get_functiondef(p.oid)like'%audit_events%'and pg_get_functiondef(p.oid)like'%event_outbox%'and pg_get_functiondef(p.oid)like'%begin_rewards_command%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['record_reward_source_event','decide_reward_award','decide_measurement_baseline'])),'new commands preserve idempotence audit and Outbox');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name=any(array['reward_source_events','reward_award_approvals','measurement_baseline_submissions','measurement_baseline_verification_decisions'])and data_type in('real','double precision')),'hardening introduces no floating point fields');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values
 ('a6900000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','reward-admin-1@example.invalid','',now(),'{}','{}',now(),now()),
 ('a6900000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','reward-admin-2@example.invalid','',now(),'{}','{}',now(),now()),
 ('a6900000-0000-4000-8000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','reward-target@example.invalid','',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name,display_name,status,created_by)values
 ('b6900000-0000-4000-8000-000000000001','Source Referral Test','Source Referral','ACTIVE','a6900000-0000-4000-8000-000000000001'),
 ('b6900000-0000-4000-8000-000000000002','Target Savings Test','Target Savings','ACTIVE','a6900000-0000-4000-8000-000000000003');
insert into public.organization_memberships(id,organization_id,user_id,status,activated_at)values
 ('c6900000-0000-4000-8000-000000000001','b6900000-0000-4000-8000-000000000002','a6900000-0000-4000-8000-000000000003','ACTIVE',now()),
 ('c6900000-0000-4000-8000-000000000002','b6900000-0000-4000-8000-000000000002','a6900000-0000-4000-8000-000000000001','ACTIVE',now());
insert into public.organization_member_roles(membership_id,role_code)values
 ('c6900000-0000-4000-8000-000000000001','CLIENT_OWNER'),('c6900000-0000-4000-8000-000000000002','CLIENT_ACCOUNTING');
insert into public.platform_user_roles(user_id,role_code)values('a6900000-0000-4000-8000-000000000001','SUPER_ADMIN'),('a6900000-0000-4000-8000-000000000002','SUPER_ADMIN');
insert into public.credit_wallets(id,organization_id,wallet_type)values('d6900000-0000-4000-8000-000000000001','b6900000-0000-4000-8000-000000000002','CLIENT');
insert into public.client_compliance_cases(id,organization_id,status,created_by)values('d6900000-0000-4000-8000-000000000010','b6900000-0000-4000-8000-000000000002','PROFILE_IN_PROGRESS','a6900000-0000-4000-8000-000000000003');
insert into public.client_compliance_evidence(id,compliance_case_id,organization_id,evidence_type,object_path,file_sha256,review_status,reviewed_by,reviewed_at,created_by)values('d6900000-0000-4000-8000-000000000011','d6900000-0000-4000-8000-000000000010','b6900000-0000-4000-8000-000000000002','TAX_DOCUMENT','tenant/security69/evidence.pdf',repeat('7',64),'VERIFIED','a6900000-0000-4000-8000-000000000001',now(),'a6900000-0000-4000-8000-000000000003');
insert into public.reward_rule_versions(id,rule_code,version_number,status,trigger_event,audience_type,bonus_credits,per_recipient_cap_credits,global_cap_credits,window_days,cooldown_hours,credit_validity_days,eligibility_rule,requires_approval,effective_from,content_hash,change_reason,created_by)values('d6900000-0000-4000-8000-000000000002','REFERRAL_BONUS',1,'ACTIVE','REFERRAL_VERIFIED','REFERRED_CLIENT',10,20,100,30,0,90,'{"verified":true}',true,clock_timestamp()-interval'1 day',repeat('a',64),'Runtime security test','a6900000-0000-4000-8000-000000000001');
insert into public.referral_links(id,source_organization_id,referral_code,audience_type,campaign_reference,status,expires_at,max_conversions,created_by,correlation_id)values('d6900000-0000-4000-8000-000000000003','b6900000-0000-4000-8000-000000000001','SECURE69','CLIENT','SECURITY_TEST','ACTIVE',clock_timestamp()+interval'30 days',10,'a6900000-0000-4000-8000-000000000001','e6900000-0000-4000-8000-000000000001');
insert into public.referral_conversions(id,referral_link_id,source_organization_id,target_organization_id,conversion_stage,origin_snapshot,registered_by,row_version)values('d6900000-0000-4000-8000-000000000004','d6900000-0000-4000-8000-000000000003','b6900000-0000-4000-8000-000000000001','b6900000-0000-4000-8000-000000000002','PROFILE_STARTED','{"channel":"runtime_test"}','a6900000-0000-4000-8000-000000000003',2);
insert into public.referral_conversion_events(referral_conversion_id,source_organization_id,from_stage,to_stage,evidence_refs,evidence_hash,correlation_id,actor_user_id)values
 ('d6900000-0000-4000-8000-000000000004','b6900000-0000-4000-8000-000000000001',null,'REGISTERED','["registration:test"]',repeat('b',64),'e6900000-0000-4000-8000-000000000002','a6900000-0000-4000-8000-000000000003'),
 ('d6900000-0000-4000-8000-000000000004','b6900000-0000-4000-8000-000000000001','REGISTERED','PROFILE_STARTED','["profile:test"]',repeat('c',64),'e6900000-0000-4000-8000-000000000003','a6900000-0000-4000-8000-000000000003');
create temporary table p19_hardening_observed(k text primary key,v jsonb);
grant select,insert on p19_hardening_observed to authenticated;

set local role authenticated;
select set_config('request.jwt.claim.sub','a6900000-0000-4000-8000-000000000003',true);
select set_config('request.jwt.claims','{"sub":"a6900000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
reset role;
select extensions.throws_ok($$set local role authenticated;select public.advance_referral_conversion('d6900000-0000-4000-8000-000000000004','VERIFIED','["self:asserted"]',repeat('c',64),2,'referral-self-verify-69')$$,'42501'::char(5),'REFERRAL_VERIFICATION_AAL2_REQUIRED','target organization cannot self-promote referral to VERIFIED');
set local role authenticated;
insert into p19_hardening_observed values('draft',public.capture_verified_baseline('b6900000-0000-4000-8000-000000000002','ORGANIZATION','b6900000-0000-4000-8000-000000000002','MONTHLY_COST',100000,'MAD','2026-01-01','2026-01-31','ACCOUNTING_EXPORT','export:jan-2026','[{"registry":"CLIENT_COMPLIANCE_EVIDENCE","id":"d6900000-0000-4000-8000-000000000011"}]',repeat('d',64),'COST-V1','baseline-submit-69'));
insert into p19_hardening_observed values('draft-replay',public.capture_verified_baseline('b6900000-0000-4000-8000-000000000002','ORGANIZATION','b6900000-0000-4000-8000-000000000002','MONTHLY_COST',100000,'MAD','2026-01-01','2026-01-31','ACCOUNTING_EXPORT','export:jan-2026','[{"registry":"CLIENT_COMPLIANCE_EVIDENCE","id":"d6900000-0000-4000-8000-000000000011"}]',repeat('d',64),'COST-V1','baseline-submit-69'));
reset role;
select is((select v->>'outcome'from p19_hardening_observed where k='draft'),'MEASUREMENT_BASELINE_DRAFT_SUBMITTED','capture creates a draft, not a verified baseline');
select is((select count(*)from public.measurement_baselines where organization_id='b6900000-0000-4000-8000-000000000002'),0::bigint,'draft capture creates no verified baseline row');
select is((select v->>'baseline_submission_id'from p19_hardening_observed where k='draft'),(select v->>'baseline_submission_id'from p19_hardening_observed where k='draft-replay'),'baseline submission replay is idempotent');

set local role authenticated;
select set_config('request.jwt.claim.sub','a6900000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"a6900000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
reset role;
select extensions.throws_ok($$set local role authenticated;select public.advance_referral_conversion('d6900000-0000-4000-8000-000000000004','VERIFIED','["central:review"]',repeat('e',64),2,'referral-aal1-verify-69')$$,'42501'::char(5),'REFERRAL_REQUEST_DENIED','central AAL1 receives the same non-disclosing denial');
select extensions.throws_ok(format($sql$set local role authenticated;select public.decide_measurement_baseline(%L::uuid,'APPROVED','Independent finance approval','baseline-review-aal1-69')$sql$,(select v->>'baseline_submission_id'from p19_hardening_observed where k='draft')),'42501'::char(5),'BASELINE_REVIEW_AAL2_REQUIRED','central AAL1 cannot approve a baseline');

set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a6900000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into p19_hardening_observed values('own-draft',public.capture_verified_baseline('b6900000-0000-4000-8000-000000000002','ORGANIZATION','b6900000-0000-4000-8000-000000000002','OWN_COST',200000,'MAD','2026-02-01','2026-02-28','SIGNED_REPORT','report:feb-2026','[{"registry":"CLIENT_COMPLIANCE_EVIDENCE","id":"d6900000-0000-4000-8000-000000000011"}]',repeat('f',64),'COST-V1','baseline-own-submit-69'));
reset role;
select extensions.throws_ok(format($sql$set local role authenticated;select public.decide_measurement_baseline(%L::uuid,'APPROVED','Self approval must be rejected','baseline-self-review-69')$sql$,(select v->>'baseline_submission_id'from p19_hardening_observed where k='own-draft')),'42501'::char(5),'BASELINE_DUAL_CONTROL_REQUIRED','baseline submitter cannot approve their own draft');
select extensions.throws_ok($$set local role authenticated;select public.award_reward('b6900000-0000-4000-8000-000000000002','d6900000-0000-4000-8000-000000000001','d6900000-0000-4000-8000-000000000002','REFERRAL_CONVERSION','d6900000-0000-4000-8000-000000000004',repeat('1',64),'{"source_event_id":"d6900000-0000-4000-8000-000000000099"}','d6900000-0000-4000-8000-000000000098','reward-no-proof-69')$$,'23514'::char(5),'APPROVED_REWARD_SOURCE_REQUIRED','reward cannot issue credits from fabricated source and approval IDs');
select is((select count(*)from public.credit_ledger_entries where organization_id='b6900000-0000-4000-8000-000000000002'),0::bigint,'failed reward evidence creates no credit ledger entry');
set local role authenticated;
insert into p19_hardening_observed values('approved',public.decide_measurement_baseline((select(v->>'baseline_submission_id')::uuid from p19_hardening_observed where k='draft'),'APPROVED','Independent finance evidence review','baseline-review-ok-69'));
insert into p19_hardening_observed values('approved-replay',public.decide_measurement_baseline((select(v->>'baseline_submission_id')::uuid from p19_hardening_observed where k='draft'),'APPROVED','Independent finance evidence review','baseline-review-ok-69'));
reset role;
select is((select v->>'outcome'from p19_hardening_observed where k='approved'),'MEASUREMENT_BASELINE_APPROVED','independent AAL2 reviewer can approve a valid baseline');
select is((select count(*)from public.measurement_baselines where id=(select(v->>'baseline_id')::uuid from p19_hardening_observed where k='approved')),1::bigint,'approval creates exactly one verified baseline');
select is((select v->>'baseline_id'from p19_hardening_observed where k='approved'),(select v->>'baseline_id'from p19_hardening_observed where k='approved-replay'),'baseline decision replay is idempotent');

reset role;
insert into public.measurement_baselines(id,organization_id,subject_type,subject_id,metric_code,version_number,baseline_amount_minor,currency,period_start,period_end,source_type,source_reference,evidence_refs,evidence_hash,methodology_version,verification_status,verified_by,correlation_id)values('d6900000-0000-4000-8000-000000000090','b6900000-0000-4000-8000-000000000002','ORGANIZATION','b6900000-0000-4000-8000-000000000002','LEGACY_COST',1,50000,'MAD','2026-03-01','2026-03-31','SIGNED_REPORT','legacy:unapproved','["legacy"]',repeat('9',64),'LEGACY-V1','VERIFIED','a6900000-0000-4000-8000-000000000001','e6900000-0000-4000-8000-000000000090');
select extensions.throws_ok($$insert into public.savings_measurements(organization_id,baseline_id,actual_amount_minor,savings_amount_minor,currency,actual_period_start,actual_period_end,source_type,source_reference,evidence_refs,evidence_hash,formula_version,explanation,recorded_by,correlation_id)values('b6900000-0000-4000-8000-000000000002','d6900000-0000-4000-8000-000000000090',40000,10000,'MAD','2026-04-01','2026-05-01','SIGNED_REPORT','actual:legacy','["actual"]',repeat('8',64),'SAVINGS-V1','{}','a6900000-0000-4000-8000-000000000001','e6900000-0000-4000-8000-000000000091')$$,'23514'::char(5),'INDEPENDENTLY_APPROVED_BASELINE_REQUIRED','legacy self-verified baseline cannot create savings');

select * from finish();
rollback;
